        graph.definition(first).unwrap(),
        Site {
            block: 0,
            statement: Some(0),
            local: 1
        }
    );
    assert_eq!(
        graph.definition(second).unwrap(),
        Site {
            block: 0,
            statement: Some(1),
            local: 2
        }
    );
}

